#include <cstddef>
#include <iostream>
#include <new>
#include <vector>

struct PreparacionFallida {};

class Serie {
public:
    std::size_t cantidad() const { return datos_.size(); }
    int valor(std::size_t posicion) const { return datos_[posicion]; }
    bool cambiar(int posicion, int valor);
    bool reemplazar(int cantidad, int valor, bool provocarFallo);
private:
    std::vector<int> datos_{3, 6};
};

bool Serie::cambiar(int posicion, int valor) {
    if (posicion < 0 || static_cast<std::size_t>(posicion) >= datos_.size()
        || valor < 0 || valor > 9) {
        return false;
    }
    datos_[static_cast<std::size_t>(posicion)] = valor;
    return true;
}

bool Serie::reemplazar(int cantidad, int valor, bool provocarFallo) {
    if (cantidad < 0 || cantidad > 4 || valor < 0 || valor > 9) {
        return false;
    }
    // Completa la preparación local, el fallo de prueba, el intercambio y las capturas.
    (void)provocarFallo;
    return false;
}

void mostrar(const Serie& serie) {
    std::cout << serie.cantidad() << ':';
    if (serie.cantidad() == 0) {
        std::cout << 'X';
    } else {
        for (std::size_t i = 0; i < serie.cantidad(); ++i) {
            if (i != 0) {
                std::cout << ',';
            }
            std::cout << serie.valor(i);
        }
    }
}

int main() {
    int cantidadOrdenes = 0;
    if (!(std::cin >> cantidadOrdenes) || cantidadOrdenes < 1 || cantidadOrdenes > 12) {
        return 1;
    }
    Serie serie;
    const Serie foto = serie;

    std::cout << "Inicio:";
    mostrar(serie);
    std::cout << '\n';
    for (int i = 0; i < cantidadOrdenes; ++i) {
        int operacion = 0;
        int a = 0;
        int b = 0;

        if (!(std::cin >> operacion >> a >> b)) {
            return 1;
        }
        bool aceptado = false;
        if (operacion == 1) {
            aceptado = serie.cambiar(a, b);
        } else if (operacion == 2 || operacion == 3) {
            aceptado = serie.reemplazar(a, b, operacion == 3);
        }
        std::cout << "Resultado:" << aceptado << ";Datos:";
        mostrar(serie);
        std::cout << '\n';
    }
    std::cout << "Foto:";
    mostrar(foto);
    return 0;
}

